#include "app.h"
#include <X11/Xlib.h>
#include <X11/Xutil.h>
#include <X11/keysym.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static void draw(Display*d,Window win,GC gc,int screen,const Program*p){XSetForeground(d,gc,WhitePixel(d,screen));XFillRectangle(d,win,gc,0,0,p->width,p->height);XSetForeground(d,gc,BlackPixel(d,screen));for(int i=0;i<p->nw;i++){const Widget*e=&p->widgets[i];char buf[200];const char*s=e->text;if(e->type==4){snprintf(buf,sizeof(buf),"%s: %lld.%02lld",s,(long long)(p->vars[e->id]/100),(long long)llabs(p->vars[e->id]%100));s=buf;}if(e->type==3){XDrawRectangle(d,win,gc,e->x,e->y,e->w,e->h);s=inputs[e->id];}if(e->type==2){XDrawRectangle(d,win,gc,e->x,e->y,e->w,e->h);}if(e->type==5){s=status;}int tx=e->x+((e->type==2||e->type==3)?10:0);int ty=e->y+((e->type==2||e->type==3)?e->h/2+5:15);XDrawString(d,win,gc,tx,ty,s,(int)strlen(s));}XFlush(d);}
int app_window(Program *p){Display*d=XOpenDisplay(NULL);if(!d){fprintf(stderr,"No X11 display; use --validate for headless testing\n");return 3;}int screen=DefaultScreen(d);Window win=XCreateSimpleWindow(d,RootWindow(d,screen),50,50,p->width,p->height,1,BlackPixel(d,screen),WhitePixel(d,screen));XStoreName(d,win,p->title);XSelectInput(d,win,ExposureMask|KeyPressMask|ButtonPressMask|StructureNotifyMask);Atom wm_delete=XInternAtom(d,"WM_DELETE_WINDOW",False);XSetWMProtocols(d,win,&wm_delete,1);GC gc=XCreateGC(d,win,0,NULL);XMapWindow(d,win);int running=1;while(running){XEvent ev;XNextEvent(d,&ev);if(ev.type==ClientMessage&&(Atom)ev.xclient.data.l[0]==wm_delete)break;if(ev.type==KeyPress){KeySym key;char chars[16];int n=XLookupString(&ev.xkey,chars,sizeof(chars),&key,NULL);if(key==XK_Escape){running=0;continue;}if(focused){size_t len=strlen(inputs[focused]);if(key==XK_BackSpace&&len)inputs[focused][len-1]=0;else if(n==1&&chars[0]>='0'&&chars[0]<='9'&&len<18){inputs[focused][len]=chars[0];inputs[focused][len+1]=0;}}}if(ev.type==ButtonPress){int x=ev.xbutton.x,y=ev.xbutton.y;for(int i=0;i<p->nw;i++){Widget*e=&p->widgets[i];if(x>=e->x&&x<=e->x+e->w&&y>=e->y&&y<=e->y+e->h){if(e->type==3)focused=e->id;if(e->type==2){for(int j=0;j<p->na;j++)if(p->actions[j].id==e->id)app_execute(p,&p->actions[j]);}break;}}}if(ev.type==Expose||ev.type==KeyPress||ev.type==ButtonPress)draw(d,win,gc,screen,p);}XFreeGC(d,gc);XDestroyWindow(d,win);XCloseDisplay(d);return 0;}
